# Surah At-Tawbah (chapter 9) — part 9: ayat 75-84 (IDs 1310-1319)
SURAH = 9

ENTRIES = {
1310: (
"اور ان میں — کوئی — اللہ — سے عہد کرتا ہے — اگر — وہ — ہمیں — اپنے فضل سے — دے تو ہم — یقیناً — صدقہ کریں گے — اور — ہم — نیکوکار — ہو جائیں گے",
"""۱۔ منافق — مال ملنے پر صدقہ کا وعدہ کرتے ہیں۔
۲۔ ’’وَمِنْهُم مَّنْ عَاهَدَ اللَّهَ لَئِنْ آتَانَا مِن فَضْلِهِ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ الصَّالِحِينَ‘‘ — اور ان میں — کوئی — اللہ — سے عہد کرتا ہے — اگر — وہ — ہمیں — اپنے فضل سے — دے تو ہم — یقیناً — صدقہ کریں گے — اور — ہم — نیکوکار — ہو جائیں گے — یعنی منافق — مال ملنے پر — صدقہ اور نیکی کا — وعدہ کرتے ہیں۔
۳۔ عملی سبق: وعدہ — مال نہ ہونے پر — بھی — پورا کرو۔"""
),
1311: (
"پس — جب — اللہ — نے — انہیں — اپنے فضل سے — دیا — تو — وہ — اس میں — بخل کرنے لگے — اور — منہ موڑ — گئے — اور — وہ — روگردانی کرنے والے تھے",
"""۱۔ وعدہ خلافی اور بخل — منافقین کا کردار۔
۲۔ ’’فَلَمَّا آتَاهُم مِّن فَضْلِهِ بَخِلُوا بِهِ وَتَوَلَّوْا وَهُم مُّعْرِضُونَ‘‘ — پس — جب — اللہ — نے — انہیں — اپنے فضل سے — دیا — تو — وہ — اس میں — بخل کرنے لگے — اور — منہ موڑ — گئے — اور — وہ — روگردانی کرنے والے تھے — یعنی مال ملنے کے بعد — منافق — بخل — اور — روگردانی — کرتے ہیں۔
۳۔ عملی سبق: مال ملنے پر — شکر اور نفقہ — کرو؛ بخل نہ کرو۔"""
),
1312: (
"پس — اس نے — ان — کے دلوں میں — نفاق — لازم کر دیا — اس دن تک — جس — روز — وہ — اس سے — ملیں گے — اس — لیے کہ انہوں نے — اللہ — سے کیا گیا وعدہ — توڑا — اور اس لیے کہ — وہ جھوٹ بولتے تھے",
"""۱۔ وعدہ خلافی اور جھوٹ — دلوں میں نفاق کا سبب۔
۲۔ ’’فَأَعْقَبَهُمْ نِفَاقًا فِي قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُ بِمَا أَخْلَفُوا اللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا يَكْذِبُونَ‘‘ — پس — اس نے — ان — کے دلوں میں — نفاق — لازم کر دیا — اس دن تک — جس — روز — وہ — اس سے — ملیں گے — اس — لیے کہ انہوں نے — اللہ — سے کیا گیا وعدہ — توڑا — اور اس لیے کہ — وہ جھوٹ بولتے تھے — یعنی وعدہ خلافی اور جھوٹ — دلوں میں — مستقل نفاق — پیدا کرتے ہیں۔
۳۔ عملی سبق: اللہ سے کیا وعدہ — پورا کرو؛ سچ بولو — ورنہ نفاق تمہارے دل میں — پختہ ہوتا ہے۔"""
),
1313: (
"کیا — وہ — نہیں جانتے — کہ — اللہ — ان کی — پوشیدہ باتیں — اور ان کی — سرگوشی — جانتا ہے — اور — یہ — کہ — اللہ — سب غیب — کا جاننے والا ہے",
"""۱۔ اللہ — سب کچھ — جانتا ہے؛ کوئی سرگوشی بھی اوجھل نہیں۔
۲۔ ’’أَلَمْ يَعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَاهُمْ وَأَنَّ اللَّهَ عَلَّامُ الْغُيُوبِ‘‘ — کیا — وہ — نہیں جانتے — کہ — اللہ — ان کی — پوشیدہ باتیں — اور ان کی — سرگوشی — جانتا ہے — اور — یہ — کہ — اللہ — سب غیب — کا جاننے والا ہے — یعنی کسی کی سرگوشی — اللہ سے پوشیدہ نہیں۔
۳۔ عملی سبق: اللہ — ہر رات کی بات — جانتا ہے؛ نفاق سے بچو۔"""
),
1314: (
"وہ — لوگ — جو — رضاکار — مؤمنوں کو — صدقات — کے بارے میں — عیب لگاتے ہیں — اور — وہ لوگ — جو — اپنی — مزدوری — کے علاوہ — کچھ نہیں پاتے — اور ان — کا — مذاق اڑاتے ہیں — اللہ — نے — ان کا — مذاق اڑایا — اور — ان کے لیے — دردناک عذاب — ہے",
"""۱۔ مفلس مؤمنوں کے — صدقہ پر — طعن — بہت بڑا گناہ۔
۲۔ ’’الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ اللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — وہ — لوگ — جو — رضاکار — مؤمنوں کو — صدقات — کے بارے میں — عیب لگاتے ہیں — اور — وہ لوگ — جو — اپنی — مزدوری — کے علاوہ — کچھ نہیں پاتے — اور ان — کا — مذاق اڑاتے ہیں — اللہ — نے — ان کا — مذاق اڑایا — اور — ان کے لیے — دردناک عذاب — ہے — یعنی اگر کوئی مؤمن — اپنی مزدوری کے بقدر — صدقہ دے — تو اسے — عیب نہ لگاؤ؛ اللہ ان کا مذاق اڑاتا ہے۔
۳۔ عملی سبق: صدقہ — خواہ تھوڑا ہی ہو — کبھی عیب نہ لگاؤ؛ اللہ دیکھتا ہے۔"""
),
1315: (
"آپؐ — ان — کے لیے — استغفار کریں — یا نہ کریں — اگر — آپ — ان — کے لیے — ستر بار — بھی استغفار کریں — اللہ — انہیں — کبھی نہ بخشے گا — یہ — اس لیے — کہ انہوں نے — اللہ اور اس کے رسولؐ — کا انکار کیا — اور — اللہ — فاسقوں — کو — ہدایت نہیں دیتا",
"""۱۔ منافقوں کے لیے استغفار — بے سود — اللہ انہیں نہیں بخشے گا۔
۲۔ ’’اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّۃً فَلَن يَغْفِرَ اللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ‘‘ — آپؐ — ان — کے لیے — استغفار کریں — یا نہ کریں — اگر — آپ — ان — کے لیے — ستر بار — بھی استغفار کریں — اللہ — انہیں — کبھی نہ بخشے گا — یہ — اس لیے — کہ انہوں نے — اللہ اور اس کے رسولؐ — کا انکار کیا — اور — اللہ — فاسقوں — کو — ہدایت نہیں دیتا — یعنی منافقین کے لیے — یہاں تک کہ نبیؐ کی دعا بھی — انہیں نہیں بچا سکتی۔
۳۔ عملی سبق: ایمان — کسی کی دعا سے نہیں — اپنے دل سے آتا ہے؛ خود ایمان لاؤ۔"""
),
1316: (
"پیچھے چھوڑ دیے جانے والے لوگ — رسولؐ — کی مخالفت میں — اپنے بیٹھنے — پر — خوش ہوئے — اور — انہوں نے — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد — کو — ناپسند کیا — اور کہا — گرمی میں — مت نکلنا — کہدو — جہنم کی آگ — بہت — زیادہ — گرم ہے — کاش — وہ سمجھتے",
"""۱۔ تبوک — پیچھے رہ جانے والے خوش ہوتے ہیں؛ گرمی کو بہانہ بناتے ہیں۔
۲۔ ’’فَرِحَ الْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَافَ رَسُولِ اللَّهِ وَكَرِهُوا أَن يُجَاهِدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ فِي سَبِيلِ اللَّهِ وَقَالُوا لَا تَنفِرُوا فِي الْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا يَفْقَهُونَ‘‘ — پیچھے چھوڑ دیے جانے والے لوگ — رسولؐ — کی مخالفت میں — اپنے بیٹھنے — پر — خوش ہوئے — اور — انہوں نے — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد — کو — ناپسند کیا — اور کہا — گرمی میں — مت نکلنا — کہدو — جہنم کی آگ — بہت — زیادہ — گرم ہے — کاش — وہ سمجھتے — یعنی پیچھے رہ جانے والے — گرمی کو بہانہ بناتے ہیں — مگر — جہنم کی آگ — زیادہ سخت ہے۔
۳۔ عملی سبق: بہانے — جہنم سے نہیں بچائیں گے؛ جہاد کرو۔"""
),
1317: (
"پس — وہ — تھوڑا ہنس لیں — اور — بہت — روئیں — اپنے کیے کا بدلہ",
"""۱۔ منافق — دنیا میں تھوڑی ہنسی — آخرت میں — بہت رونا۔
۲۔ ’’فَلْيَضْحَكُوا قَلِيلًا وَلْيَبْكُوا كَثِيرًا جَزَاءً بِمَا كَانُوا يَكْسِبُونَ‘‘ — پس — وہ — تھوڑا ہنس لیں — اور — بہت — روئیں — اپنے کیے کا بدلہ — یعنی دنیا کی ہنسی — جہنم میں — بہت رونے میں بدل جاتی ہے۔
۳۔ عملی سبق: دنیا کی ہنسی — آخرت کی روانگی — کا سبب ہے؛ سنجیدگی اختیار کرو۔"""
),
1318: (
"پس — اگر — اللہ — آپ کو — ان — کے ایک — گروہ — کی طرف — واپس لوٹائے — تو — وہ — آپ سے — اجازت مانگیں — باہر نکلنے کی — تو کہدو — تم — اب — کبھی نہ نکل سکو گے — اور — نہ — تم میرے ساتھ — دشمن سے — کبھی لڑو گے — بے شک — تم — پہلے ہی بار — بیٹھنے پر راضی ہوئے — پس — بیٹھے — بیٹھے — والوں — کے ساتھ — بیٹھ جاؤ",
"""۱۔ واپس لوٹنے پر — پیچھے رہ جانے والے — قابلِ اعتبار نہیں۔
۲۔ ’’فَإِن رَّجَعَكَ اللَّهُ إِلَىٰ طَائِفَۃٍ مِّنْهُمْ فَاسْتَأْذَنُوكَ لِلْخُرُوجِ فَقُلْ لَّن تَخْرُجُوا مَعِيَ أَبَدًا وَلَن تُقَاتِلُوا مَعِيَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِالْقُعُودِ أَوَّلَ مَرَّۃٍ فَاقْعُدُوا مَعَ الْخَالِفِينَ‘‘ — پس — اگر — اللہ — آپ کو — ان — کے ایک — گروہ — کی طرف — واپس لوٹائے — تو — وہ — آپ سے — اجازت مانگیں — باہر نکلنے کی — تو کہدو — تم — اب — کبھی نہ نکل سکو گے — اور — نہ — تم میرے ساتھ — دشمن سے — کبھی لڑو گے — بے شک — تم — پہلے ہی بار — بیٹھنے پر راضی ہوئے — پس — بیٹھے — بیٹھے — والوں — کے ساتھ — بیٹھ جاؤ — یعنی منافق — ہمیشہ — جہاد سے — بچتے رہیں گے — انہیں — چھوڑنا — بہتر ہے۔
۳۔ عملی سبق: نفاق — ایک بار میں — پہچان لیا جاتا ہے۔"""
),
1319: (
"اور — ان — میں سے — کسی پر — نماز — نہ پڑھو — جس — کی وہ — وفات بھی ہو — اور — نہ — اس کی قبر پر — کھڑے ہو — بے شک — انہوں نے — اللہ اور اس کے رسولؐ — کا انکار کیا — اور — وہ — فاسق — حالت میں — مردہ ہوئے",
"""۱۔ منافق — کی نمازِ جنازہ — جائز نہیں۔
۲۔ ’’وَلَا تُصَلِّ عَلَىٰ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِ إِنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَمَاتُوا وَهُمْ فَاسِقُونَ‘‘ — اور — ان — میں سے — کسی پر — نماز — نہ پڑھو — جس — کی وہ — وفات بھی ہو — اور — نہ — اس کی قبر پر — کھڑے ہو — بے شک — انہوں نے — اللہ اور اس کے رسولؐ — کا انکار کیا — اور — وہ — فاسق — حالت میں — مردہ ہوئے — یعنی منافق — کے لیے — نمازِ جنازہ — نہیں پڑھی جاتی — اور نہ — اس کی قبر پر — دعا — کی جاتی ہے۔
۳۔ عملی سبق: نفاق — یہاں تک کہ مرنے کے بعد بھی — اپنے ساتھ — جاتا ہے۔"""
),
}
